interface Comparable<T> { int compareTo(T o); }   // контракт, can-do
interface Repository<T> { T findById(long id); }

abstract class Animal {                              // общая реализация + состояние
  protected String name;
  Animal(String n) { this.name = n; }
  abstract String sound();
  void breathe() { System.out.println(name + " дышит"); }
}
class Dog extends Animal implements Comparable<Dog> {
  Dog(String n) { super(n); }
  String sound() { return "гав"; }
  public int compareTo(Dog o) { return name.compareTo(o.name); }
}
```

